actions.action:
config_status: f.config_status, config_message: f.config_message;
def others = findCases { it.processIdentifier.eq(net_prefix(useCase) + "ai_config") }
        .findAll { c -> c.stringId != useCase.stringId }
if (others) {
    change config_status value { "invalid" }
    change config_message value { "Duplicitná konfigurácia - používaj pôvodný case" }
    changeCaseProperty("color").about { "red" }
} else {
    change config_status value { "invalid" }
    change config_message value { "Vyber konfiguráciu a klikni Aktivovať" }
    changeCaseProperty("title").about { "AI konfigurácia" }
}

document.function:
{ def caseObj ->
    // Na single-tenant Netgrif Platforme premenna workspace neexistuje a
    // processIdentifier je bez prefixu. Odvodime ho z vlastneho casu - funguje
    // rovnako na single-tenante (prazdny prefix) aj na multi-tenant eTasku.
    def pid = caseObj.processIdentifier
    return pid.contains("/") ? pid.substring(0, pid.lastIndexOf("/") + 1) : ""
}

{ def key ->
    // Mongo nepovoluje bodku ani dolar v kluci mapy - options preto nesu slug,
    // realny API kluc zostava v models_json a dohladava sa cez slug.
    return (key as String).replace(".", "__D__").replace('$', "__S__")
}

{ models_json, models_local, models_external ->
    def list = models_json.value ? new groovy.json.JsonSlurper().parseText(models_json.value) : []
    def label = { m -> (m.provider ? (m.label + "  [" + m.provider + "]") : m.label) as String }
    change models_local options {
        list.findAll { m -> m.origin == "local" }.collectEntries { m -> [(model_slug(m.key)): label(m)] }
    }
    change models_external options {
        list.findAll { m -> m.origin == "external" }.collectEntries { m -> [(model_slug(m.key)): label(m)] }
    }
}

{ settings_selector ->
    def prefix = net_prefix(useCase)
    change settings_selector options {
        findCases { it.processIdentifier.eq(prefix + "single_settings") }
                .collectEntries { c -> [(c.stringId): (c.getFieldValue("settings_name") ?: c.stringId)] }
    }
}

actions.action:
new_model_key: f.new_model_key, new_model_label: f.new_model_label,
new_model_provider: f.new_model_provider,
models_json: f.models_json, codebook_message: f.codebook_message,
models_local: f.models_local, models_external: f.models_external;

def key = ((new_model_key.value ?: "") as String).trim()
if (!key) {
    change codebook_message value { "Vyplň kľúč modelu." }
} else {
    def list = models_json.value ? new groovy.json.JsonSlurper().parseText(models_json.value) : []
    if (list.any { m -> m.key == key }) {
        change codebook_message value { "Model " + key + " už v číselníku je." }
    } else {
        def prov = (new_model_provider.value ?: "custom") as String
        def label = ((new_model_label.value ?: "") as String).trim() ?: key
        list.add([key: key, label: label, origin: (prov == "local") ? "local" : "external", provider: prov])
        change models_json value { groovy.json.JsonOutput.toJson(list) }
        change codebook_message value { "Pridaný: " + label + "  [" + prov + "]" }
        change new_model_key value { "" }
        change new_model_label value { "" }
        render_codebook(models_json, models_local, models_external)
    }
}

models_local: f.models_local, models_external: f.models_external,
models_json: f.models_json, codebook_message: f.codebook_message;

def list = models_json.value ? new groovy.json.JsonSlurper().parseText(models_json.value) : []
def toRemove = (((models_local.value ?: []) as List) + ((models_external.value ?: []) as List)) as Set
if (!toRemove) {
    change codebook_message value { "Nič nie je zaškrtnuté." }
} else {
    def kept = list.findAll { m -> !(model_slug(m.key) in toRemove) }
    change models_json value { groovy.json.JsonOutput.toJson(kept) }
    change models_local value { [] }
    change models_external value { [] }
    change codebook_message value { "Odobraté: " + (list.size() - kept.size()) }
    render_codebook(models_json, models_local, models_external)
}

settings_selector: f.settings_selector, settings_preview: f.settings_preview,
settings_case_id: f.settings_case_id;

change settings_case_id value { settings_selector.value }
if (settings_selector.value) {
    def t = findTask { it.transitionId.eq("t_settings").and(it.caseId.eq(settings_selector.value)) }
    if (t) {
        def free = findTask {
            it.transitionId.eq("t_settings")
                    .and(it.caseId.eq(settings_selector.value))
                    .and(it.userId.isNull())
        }
        if (free) assignTask(free)
        change settings_preview value { [t.stringId] }
    } else {
        change settings_preview value { [] }
    }
} else {
    change settings_preview value { [] }
}

settings_selector: f.settings_selector, settings_preview: f.settings_preview,
settings_case_id: f.settings_case_id;

def c = createCase(net_prefix(useCase) + "single_settings")
def t = findTask { it.transitionId.eq("t_settings").and(it.caseId.eq(c.stringId)) }
if (t) assignTask(t)
load_settings_options(settings_selector)
change settings_selector value { c.stringId }
change settings_case_id value { c.stringId }
change settings_preview value { t ? [t.stringId] : [] }

settings_selector: f.settings_selector, models_json: f.models_json,
active_settings_name: f.active_settings_name, active_origin: f.active_origin,
active_model_key: f.active_model_key, active_model_label: f.active_model_label,
active_provider: f.active_provider,
active_system_prompt: f.active_system_prompt, active_user_prompt: f.active_user_prompt,
active_temperature: f.active_temperature, active_max_tokens: f.active_max_tokens,
activated_at: f.activated_at, activated_by: f.activated_by,
config_status: f.config_status, config_message: f.config_message;

def sc = settings_selector.value ? findCase { it._id.eq(settings_selector.value) } : null
if (!sc) {
    change config_status value { "invalid" }
    change config_message value { "Nie je vybraná konfigurácia" }
    changeCaseProperty("color").about { "red" }
} else {
    // Bezpecne citanie z vybraneho casu. getFieldValue by na poli, ktore v starsej
    // verzii siete neexistovalo, spadlo - dataSet[id]?.value vrati null.
    def sv = { String id -> sc.dataSet[id]?.value }

    def selModel = sv("model_key")
    def selOrigin = sv("origin")

    change active_settings_name value { sv("settings_name") }
    change active_origin        value { selOrigin }
    change active_model_key     value { selModel }
    change active_model_label   value { sv("model_label") }
    change active_system_prompt value { sv("system_prompt") }
    change active_user_prompt   value { sv("user_prompt") }
    change active_temperature   value { sv("temperature") }
    change active_max_tokens    value { sv("max_tokens") }
    // active_provider je novsie pole - v case zalozenom zo starsej verzie siete
    // chyba a import by vratil null, co by zhodilo celu akciu.
    if (active_provider != null) {
        change active_provider value { sv("model_provider") }
    }

    def list = models_json.value ? new groovy.json.JsonSlurper().parseText(models_json.value) : []
    def entry = list.find { m -> m.key == selModel }
    def problems = []
    if (!selModel) problems.add("nie je vybraný model")
    if (selModel && !entry) problems.add("model nie je v číselníku")
    if (entry && entry.origin != selOrigin) problems.add("model nepatrí k zvolenému pôvodu")
    if (!sv("system_prompt")) problems.add("chýba system prompt")
    if (!sv("user_prompt")) problems.add("chýba user prompt")

    change config_status value { problems ? "invalid" : "ok" }
    change config_message value { problems ? problems.join(", ") : "Konfigurácia je platná" }
    change activated_at value { java.time.LocalDateTime.now() }
    change activated_by value { userService.loggedOrSystem.email }
    changeCaseProperty("color").about { problems ? "red" : "green" }
}

