stale_signal: f.stale_signal, settings_case_id: f.settings_case_id,
config_status: f.config_status, config_message: f.config_message;

if (stale_signal.value && stale_signal.value == settings_case_id.value && config_status.value == "ok") {
    change config_status value { "stale" }
