actions.action:
test_input_mode: f.test_input_mode, test_result: f.test_result,
mail_from: f.mail_from, mail_to: f.mail_to, mail_subject: f.mail_subject,
mail_body: f.mail_body, mail_attachments: f.mail_attachments,
test_zip: f.test_zip, test_json: f.test_json,
config_status: f.config_status,
active_model_key: f.active_model_key, active_origin: f.active_origin,
active_provider: f.active_provider,
active_system_prompt: f.active_system_prompt, active_user_prompt: f.active_user_prompt,
active_temperature: f.active_temperature, active_max_tokens: f.active_max_tokens;

def mode = (test_input_mode.value ?: "form") as String

if (config_status.value != "ok") {
    change test_result value { "Konfigurácia nie je platná. Najprv klikni Aktivovať konfiguráciu." }
} else if (mode == "zip" && test_zip.value == null) {
    change test_result value { "Nahraj ZIP a klikni znova." }
} else if (mode == "json" && !((test_json.value ?: "") as String).trim()) {
    change test_result value { "Vlož JSON a klikni znova." }
} else {
    def params = [
            caseId         : useCase.stringId,
            modelKey       : active_model_key.value,
            provider       : active_provider.value,
            origin         : active_origin.value,
            systemPrompt   : active_system_prompt.value,
            userPrompt     : active_user_prompt.value,
            temperature    : active_temperature.value,
            maxTokens      : active_max_tokens.value,
            inputMode      : mode,
            mailFrom       : mail_from.value,
            mailTo         : mail_to.value,
            mailSubject    : mail_subject.value,
            mailBody       : mail_body.value,
            mailAttachments: mail_attachments.value,
            mailJson       : test_json.value,
            zipFieldId     : "test_zip"
    ]
    try {
        // callAIToolByConfig je metoda v EtaskActionDelegate, vola sa priamo.
        def res = callAIToolByConfig(params)
        change test_result value { res as String }
    } catch (Exception e) {
        def safe = new LinkedHashMap(params)
        safe.remove("mailBody")
        safe.remove("mailAttachments")
        safe.remove("mailJson")
        change test_result value {
            "Volanie backendu zlyhalo: " + e.getClass().getSimpleName() + " - " + e.message +
            "\n\nOdoslané parametre (bez obsahu komunikácie):\n" +
            groovy.json.JsonOutput.prettyPrint(groovy.json.JsonOutput.toJson(safe))
        }
    }
}
